// Pure parsing of `git status --porcelain` and of destructive git commands, and the list of what each would lose.

export type GitOp = "reset-hard" | "clean" | "checkout" | "stash-drop" | "stash-clear"

export interface StatusEntry {
  path: string
  /** Index (staged) status, "." when unchanged. "?" untracked, "!" ignored. */
  x: string
  /** Work tree (unstaged) status, "." when unchanged. */
  y: string
  conflict?: boolean
  /** A submodule (porcelain v2 only). reset --hard and checkout leave its files alone without --recurse-submodules. */
  submodule?: boolean
}

export interface GitStatus {
  branch: string
  upstream: string
  ahead: number
  behind: number
  entries: StatusEntry[]
}

export interface ParsedGitCommand {
  op: GitOp
  /** reset --hard target, or the checkout/restore source; "" means HEAD / the index. */
  target: string
  paths: string[]
  /** clean: -d, -x, -X, -f, -n, -i. checkout/restore: staged (also restores the index). */
  flags: { d?: boolean; x?: boolean; X?: boolean; f?: boolean; n?: boolean; i?: boolean; staged?: boolean; worktree?: boolean; recurse?: boolean; force?: boolean }
  /** clean: `-e`/`--exclude` patterns, which keep matching files. */
  exclude?: string[]
  stashRef: string
}

export interface Commit {
  sha: string
  subject: string
}

export interface StashEntry {
  /** e.g. "stash@{0}". Defaults to its position in the list. */
  ref?: string
  /** Full commit id, printed by `git stash list --format=%H`; lets the user recover a dropped stash. */
  sha?: string
  message: string
  /** Files in the stash with their +/- lines (`git stash show --numstat`). */
  files?: { path: string; added: number | null; removed: number | null }[]
}

export type LostReason = "modified" | "staged" | "new" | "conflict" | "untracked" | "ignored"

export interface LostFile {
  path: string
  reason: LostReason
  added: number | null
  removed: number | null
  /** Ignored files that are hard to get back (.env, keys, local databases), sorted first. */
  precious?: boolean
  /** Ignored files a build or install recreates (node_modules/, dist/…). */
  rebuildable?: boolean
}

export interface LossReport {
  command: ParsedGitCommand | null
  files: LostFile[]
  commits: Commit[]
  /** How many of `commits` exist only on this machine. */
  unpushed: number
  /** The shas of those commits: from the `unpushed` input when given, else the newest `ahead` ones (exact for linear history). */
  unpushedShas: string[]
  /** HEAD isn't on a branch, so commits it moves past are only kept by the reflog. */
  detached: boolean
  stashes: StashEntry[]
  /** Things people expect to lose but won't, e.g. untracked files under reset --hard. */
  kept: { untracked: number; ignored: number; staged: number; dirs: number; excluded: number; submodules: number }
  /** clean without -f, -n dry run, or restore --staged: nothing is deleted. */
  harmless: "" | "needs-force" | "dry-run" | "unstage-only"
  missingStash: boolean
}

const clean = (text: unknown) => (typeof text === "string" ? text.replace(/^\uFEFF/, "").slice(0, 2_000_000) : "")

/** Undo git's C-style quoting: "caf\303\251 \"x\".txt" → café "x".txt */
export function unquotePath(raw: string) {
  if (!raw.startsWith('"') || !raw.endsWith('"') || raw.length < 2) return raw
  const bytes: number[] = []
  const body = raw.slice(1, -1)
  const map: Record<string, number> = { n: 10, t: 9, r: 13, b: 8, f: 12, v: 11, a: 7, '"': 34, "\\": 92 }
  for (let i = 0; i < body.length; i++) {
    const ch = body[i]
    if (ch === "\\" && i + 1 < body.length) {
      const oct = body.slice(i + 1, i + 4)
      if (/^[0-7]{3}$/.test(oct)) {
        bytes.push(parseInt(oct, 8))
        i += 3
      } else {
        bytes.push(map[body[i + 1]] ?? body.charCodeAt(i + 1))
        i += 1
      }
    } else bytes.push(...new TextEncoder().encode(ch))
  }
  return new TextDecoder().decode(new Uint8Array(bytes))
}

/** Reads `git status --porcelain` v1 or v2, with or without -z and --branch. Garbage lines are skipped. */
export function parsePorcelain(input: unknown): GitStatus {
  const text = clean(input)
  const status: GitStatus = { branch: "", upstream: "", ahead: 0, behind: 0, entries: [] }
  const z = text.includes("\0")
  const lines = z ? text.split("\0") : text.split(/\r?\n/)
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    if (!line) continue
    const path = (p: string) => (z ? p : unquotePath(p))
    if (line.startsWith("# branch.head ")) status.branch = line.slice(14)
    else if (line.startsWith("# branch.upstream ")) status.upstream = line.slice(18)
    else if (line.startsWith("# branch.ab ")) {
      const m = line.match(/\+(\d+) -(\d+)/)
      if (m) [status.ahead, status.behind] = [Number(m[1]), Number(m[2])]
    } else if (line.startsWith("## ")) {
      const m = line.slice(3).match(/^(.+?)(?:\.\.\.(\S+))?(?: \[(.*)\])?$/)
      status.branch = m?.[1].replace(/^No commits yet on /, "") ?? ""
      status.upstream = m?.[2] ?? ""
      status.ahead = Number(m?.[3]?.match(/ahead (\d+)/)?.[1] ?? 0)
      status.behind = Number(m?.[3]?.match(/behind (\d+)/)?.[1] ?? 0)
    } else if (/^[12u] /.test(line)) {
      const parts = line.split(" ")
      const xy = parts[1] ?? ".."
      const fields = line[0] === "1" ? 8 : line[0] === "2" ? 9 : 10
      let p = parts.slice(fields).join(" ")
      if (line[0] === "2") {
        if (z) i++ // original path is the next NUL field
        else p = p.split("\t")[0]
      }
      if (p) status.entries.push({ path: path(p), x: xy[0], y: xy[1] ?? ".", conflict: line[0] === "u" || undefined, submodule: parts[2]?.startsWith("S") || undefined })
    } else if (/^[?!] /.test(line)) status.entries.push({ path: path(line.slice(2)), x: line[0], y: line[0] })
    else if (/^[ MTADRCU?!]{2} /.test(line)) {
      const x = line[0] === " " ? "." : line[0]
      const y = line[1] === " " ? "." : line[1]
      let p = line.slice(3)
      if (x === "R" || x === "C") {
        if (z) i++
        else p = p.split(" -> ").pop() ?? p
      }
      const conflict = x === "U" || y === "U" || (x === "A" && y === "A") || (x === "D" && y === "D")
      status.entries.push({ path: path(p), x: x === "?" || x === "!" ? x : x, y, conflict: conflict || undefined })
    }
  }
  return status
}

/** Reads `git diff --numstat`. Binary files ("-\t-") come back as null counts. */
export function parseNumstat(input: unknown) {
  const map = new Map<string, { added: number | null; removed: number | null }>()
  for (const line of clean(input).split(/\r?\n/)) {
    const m = line.match(/^(\d+|-)\t(\d+|-)\t(.+)$/)
    if (!m) continue
    // Renames: "src/{a.ts => b.ts}" or "a.ts => b.ts"
    const p = m[3].replace(/\{[^}]* => ([^}]*)\}/, "$1").replace(/^.* => /, "").replace(/\/\//g, "/")
    map.set(unquotePath(p), { added: m[1] === "-" ? null : Number(m[1]), removed: m[2] === "-" ? null : Number(m[2]) })
  }
  return map
}

/** Reads `git log --oneline` (or `%H %s`). */
export function parseLog(input: unknown): Commit[] {
  return clean(input).split(/\r?\n/).flatMap((line) => {
    const m = line.trim().match(/^([0-9a-f]{4,64})\s+(.*)$/i)
    return m ? [{ sha: m[1], subject: m[2] }] : []
  })
}

/** Shell words, honouring quotes, up to the first `&&`, `||`, `;` or `|`. */
function shellWords(text: string) {
  const out: string[] = []
  let cur = ""
  let quote = ""
  let has = false
  for (let i = 0; i < text.length; i++) {
    const ch = text[i]
    if (quote) {
      if (ch === quote) quote = ""
      else if (ch === "\\" && quote === '"' && i + 1 < text.length) cur += text[++i]
      else cur += ch
    } else if (ch === "'" || ch === '"') (quote = ch), (has = true)
    else if (ch === "\\" && i + 1 < text.length) (cur += text[++i]), (has = true)
    else if (/[;&|]/.test(ch)) break
    else if (/\s/.test(ch)) {
      if (has || cur) out.push(cur)
      cur = ""
      has = false
    } else (cur += ch), (has = true)
  }
  if (has || cur) out.push(cur)
  return out
}

// Global options before the subcommand; the listed ones take a value.
const GLOBAL_WITH_VALUE = new Set(["-c", "-C", "--git-dir", "--work-tree", "--namespace", "--exec-path", "--config-env"])

/** Recognises reset --hard, clean, checkout/restore of paths, checkout -f / switch --discard-changes, stash drop and stash clear. Anything else is null. */
export function parseGitCommand(input: unknown): ParsedGitCommand | null {
  const all = shellWords(clean(input).replace(/^\$\s+/, "").trim()).slice(0, 200)
  if (all[0] !== "git") return null
  let at = 1
  while (at < all.length && all[at].startsWith("-")) at += GLOBAL_WITH_VALUE.has(all[at]) ? 2 : 1
  const [sub, ...rest] = all.slice(at)
  const dash = rest.indexOf("--")
  const before = dash < 0 ? rest : rest.slice(0, dash)
  const after = dash < 0 ? [] : rest.slice(dash + 1)
  // Short flags can be bundled: -SW, -fdx.
  const short = (letter: string) => before.some((w) => /^-[a-zA-Z]+$/.test(w) && w.includes(letter))
  const recurse = before.includes("--recurse-submodules") || undefined
  const base: ParsedGitCommand = { op: "reset-hard", target: "", paths: [], flags: {}, stashRef: "" }
  if (sub === "reset" && before.includes("--hard")) return { ...base, target: before.find((w) => !w.startsWith("-")) ?? "", flags: { recurse } }
  if (sub === "clean") {
    const flags: ParsedGitCommand["flags"] = {}
    const paths: string[] = [...after]
    const exclude: string[] = []
    for (let i = 0; i < before.length; i++) {
      const w = before[i]
      if (w === "-e" || w === "--exclude") exclude.push(before[++i] ?? "")
      else if (w.startsWith("--exclude=")) exclude.push(w.slice(10))
      else if (/^-e./.test(w)) exclude.push(w.slice(2))
      else if (w === "--force") flags.f = true
      else if (w === "--dry-run") flags.n = true
      else if (w === "--interactive") flags.i = true
      else if (/^-[a-zA-Z]+$/.test(w)) for (const c of w.slice(1)) flags[c as "d"] = true
      else if (!w.startsWith("-")) paths.push(w)
    }
    return { ...base, op: "clean", flags, paths, exclude: exclude.filter(Boolean) }
  }
  if (sub === "checkout" || sub === "restore" || sub === "switch") {
    const force = sub === "switch" ? before.includes("--discard-changes") || short("f") || before.includes("--force") : sub === "checkout" && (short("f") || before.includes("--force"))
    const source = before.find((w) => w.startsWith("--source="))?.slice(9) ?? before.find((w, i) => before[i - 1] === "-s" || before[i - 1] === "--source") ?? ""
    const paths = sub === "switch" ? [] : dash >= 0 ? after : sub === "restore" ? before.filter((w, i) => !w.startsWith("-") && before[i - 1] !== "-s" && before[i - 1] !== "--source") : before.filter((w) => w === "." || w.includes("/") || w.includes("."))
    if (!paths.length) {
      // `git checkout -f main` / `git switch --discard-changes main` throw away every tracked change, staged or not.
      if (force) return { ...base, op: "checkout", target: before.find((w) => !w.startsWith("-")) ?? "", paths: ["."], flags: { staged: true, worktree: true, force: true, recurse } }
      return null // A plain branch switch: git refuses if it would lose changes.
    }
    const target = sub === "checkout" ? before.find((w) => !w.startsWith("-") && !paths.includes(w)) ?? "" : source
    const staged = before.includes("--staged") || short("S")
    const worktree = sub === "checkout" || before.includes("--worktree") || short("W") || !staged
    return { ...base, op: "checkout", target, paths, flags: { staged: sub === "checkout" ? !!target : staged, worktree, recurse } }
  }
  const stashArg = before.slice(1).find((w) => !w.startsWith("-"))
  if (sub === "stash" && before[0] === "drop") return { ...base, op: "stash-drop", stashRef: stashArg ?? "stash@{0}" }
  if (sub === "stash" && before[0] === "clear") return { ...base, op: "stash-clear" }
  return null
}

const PRECIOUS = /(^|\/)(\.env(\.[\w-]+)?|[^/]*\.(pem|key|p12|pfx|keystore|jks|sqlite3?|db)|\.vscode\/|\.idea\/|[^/]*\.local(\.\w+)?|credentials[^/]*|id_(rsa|ed25519|ecdsa)[^/]*)$/i
const EXAMPLE_ENV = /\.env\.(example|sample|template|dist)$/i
const REBUILDABLE = /(^|\/)(node_modules|dist|build|out|\.next|\.nuxt|\.svelte-kit|\.turbo|\.cache|\.parcel-cache|coverage|target|__pycache__|\.pytest_cache|\.venv|venv|vendor)(\/|$)|\.(pyc|log|tsbuildinfo)$|(^|\/)\.DS_Store$/i
/** clean's -e patterns follow .gitignore rules; this covers names, globs and folder patterns. */
const excluded = (path: string, patterns: string[]) =>
  patterns.some((raw) => {
    const p = raw.replace(/^\.\//, "").replace(/\/$/, "")
    const re = new RegExp("^" + p.replace(/[.+^$()|[\]\\{}]/g, "\\$&").replace(/\*\*/g, "\u0000").replace(/\*/g, "[^/]*").replace(/\?/g, "[^/]").replace(/\u0000/g, ".*") + "(/.*)?$")
    const bare = path.replace(/\/$/, "")
    return p.includes("/") ? re.test(bare) : bare.split("/").some((_, i, parts) => re.test(parts.slice(i).join("/")))
  })
const isHead = (target: string) => !target || target === "HEAD" || target === "@"
const inPaths = (path: string, paths: string[]) =>
  !paths.length || paths.some((p) => {
    const norm = p.replace(/^\.\//, "").replace(/\/$/, "")
    return norm === "." || norm === "" || norm === ":/" || path === norm || path.startsWith(norm + "/")
  })

/** Exactly what `command` would destroy, given the repo's status (and diff counts, commits or stashes when relevant). */
export function whatWillBeLost(input: { command: unknown; status: unknown; numstat?: unknown; commits?: unknown; stashes?: StashEntry[]; unpushed?: unknown }): LossReport {
  const command = parseGitCommand(input.command)
  const status = parsePorcelain(input.status)
  const counts = parseNumstat(input.numstat)
  const detached = status.branch === "(detached)" || status.branch === "HEAD (no branch)"
  const report: LossReport = { command, files: [], commits: [], unpushed: 0, unpushedShas: [], detached, stashes: [], kept: { untracked: 0, ignored: 0, staged: 0, dirs: 0, excluded: 0, submodules: 0 }, harmless: "", missingStash: false }
  if (!command) return report
  const count = (path: string) => counts.get(path) ?? { added: null, removed: null }
  const tracked = status.entries.filter((e) => e.x !== "?" && e.x !== "!")
  const untracked = status.entries.filter((e) => e.x === "?")
  const ignored = status.entries.filter((e) => e.x === "!")

  const skipSubmodule = (e: StatusEntry) => {
    if (!e.submodule || command.flags.recurse) return false
    report.kept.submodules++
    return true
  }
  if (command.op === "reset-hard") {
    for (const e of tracked) {
      if (skipSubmodule(e)) continue
      // A deletion coming back isn't lost work.
      if ((e.x === "D" || e.x === ".") && (e.y === "D" || e.y === ".") && !e.conflict) continue
      const reason: LostReason = e.conflict ? "conflict" : e.x === "A" ? "new" : e.y !== "." ? "modified" : "staged"
      report.files.push({ path: e.path, reason, ...count(e.path) })
    }
    report.kept.untracked = untracked.length
    report.kept.ignored = ignored.length
    if (!isHead(command.target)) {
      const commits = Array.isArray(input.commits) ? (input.commits as Commit[]).filter((c) => c && typeof c.sha === "string") : parseLog(input.commits)
      report.commits = commits
      // Exact list from `git rev-list @{u}..HEAD` when given; otherwise the newest `ahead` ones, which holds for linear history.
      const exact = Array.isArray(input.unpushed) ? input.unpushed.map(String) : typeof input.unpushed === "string" ? parseLog(input.unpushed.replace(/^([0-9a-f]{4,64})\s*$/gim, "$1 -")).map((c) => c.sha) : null
      const same = (a: string, b: string) => a.length >= 4 && b.length >= 4 && (a.startsWith(b) || b.startsWith(a))
      report.unpushedShas = exact ? commits.filter((c) => exact.some((sha) => same(sha, c.sha))).map((c) => c.sha) : commits.slice(0, status.upstream && !detached ? status.ahead : commits.length).map((c) => c.sha)
      report.unpushed = report.unpushedShas.length
    }
  } else if (command.op === "clean") {
    const { f, n, i, d, x, X } = command.flags
    if (n) report.harmless = "dry-run"
    else if (!f && !i) report.harmless = "needs-force"
    const pick = (list: StatusEntry[], reason: LostReason) => {
      for (const e of list) {
        if (!inPaths(e.path, command.paths)) continue
        if (excluded(e.path, command.exclude ?? [])) {
          report.kept.excluded++
          continue
        }
        if (e.path.endsWith("/") && !d) {
          report.kept.dirs++
          continue
        }
        const precious = reason === "ignored" && PRECIOUS.test(e.path.replace(/\/$/, "/")) && !EXAMPLE_ENV.test(e.path)
        report.files.push({ path: e.path, reason, added: null, removed: null, precious: precious || undefined, rebuildable: (!precious && REBUILDABLE.test(e.path)) || undefined })
      }
    }
    if (!X) pick(untracked, "untracked")
    else report.kept.untracked = untracked.length
    if (x || X) pick(ignored, "ignored")
    else report.kept.ignored = ignored.length
    report.files.sort((a, b) => Number(!!b.precious) - Number(!!a.precious) || Number(!!a.rebuildable) - Number(!!b.rebuildable))
  } else if (command.op === "checkout") {
    const { staged, worktree } = command.flags
    if (!worktree) report.harmless = "unstage-only"
    for (const e of tracked) {
      if (!inPaths(e.path, command.paths) || skipSubmodule(e)) continue
      const unstaged = e.y !== "." && e.y !== "D"
      const stagedChange = e.x !== "." && e.x !== "D"
      // Git refuses to check out unmerged paths, so conflicts are never silently lost here.
      if (e.conflict) continue
      if (worktree && (unstaged || (staged && stagedChange))) report.files.push({ path: e.path, reason: unstaged ? "modified" : e.x === "A" ? "new" : "staged", ...count(e.path) })
      else if (stagedChange) report.kept.staged++
    }
    report.kept.untracked = untracked.filter((e) => inPaths(e.path, command.paths)).length
  } else {
    const list = (input.stashes ?? []).map((s, i) => ({ ...s, ref: s.ref ?? `stash@{${i}}` }))
    const ref = command.stashRef.replace(/^stash@\{(\d+)\}$/, "stash@{$1}").replace(/^(\d+)$/, "stash@{$1}")
    report.stashes = command.op === "stash-clear" ? list : list.filter((s) => s.ref === ref)
    report.missingStash = command.op === "stash-drop" && report.stashes.length === 0
  }
  return report
}

/** The stash command that keeps everything this command would delete. */
export function stashFirstCommand(command: ParsedGitCommand | null) {
  if (!command || command.op === "stash-drop" || command.op === "stash-clear") return ""
  const scope = command.op === "clean" ? (command.flags.x || command.flags.X ? " --all" : " --include-untracked") : ""
  const paths = command.op !== "reset-hard" && command.paths.length && !command.paths.every((p) => p === ".") ? ` -- ${command.paths.join(" ")}` : ""
  return `git stash push${scope} -m "before ${command.op === "reset-hard" ? "reset --hard" : command.op}"${paths}`
}

"use client"

import * as React from "react"
import { Archive, CircleCheck, FileWarning, GitCommitHorizontal, History, Info, Loader2, TriangleAlert } from "lucide-react"

import { cn } from "@/lib/utils"
import { stashFirstCommand, whatWillBeLost, type Commit, type LostFile, type StashEntry } from "./git-loss"

export { parseGitCommand, parseLog, parseNumstat, parsePorcelain, stashFirstCommand, unquotePath, whatWillBeLost, type Commit, type GitOp, type GitStatus, type LossReport, type LostFile, type LostReason, type ParsedGitCommand, type StashEntry, type StatusEntry } from "./git-loss"

/** Every visible string. `{count}`, `{files}`, `{commits}`, `{unpushed}`, `{lines}`, `{hidden}`, `{sha}`, `{ref}` are filled in. */
export const RESET_HARD_MESSAGES = {
  summaryFiles: "Deletes uncommitted work in {files}.",
  linesSuffix: " ({lines} lines)",
  summaryCommits: "Moves the branch back past {commits}.",
  summaryUnpushed: "Not pushed anywhere yet: {unpushed}.",
  summaryStash: "Deletes {stashes} for good.",
  nothing: "Nothing will be lost. There are no changes this command would touch.",
  unknown: "This isn't reset --hard, clean, checkout/restore of paths, checkout -f or stash drop, so there's nothing to read back.",
  "needs-force": "Git will refuse this without -f (unless clean.requireForce is off). This is what -f would delete:",
  "dry-run": "-n only lists files, so nothing is deleted. This is what it would delete without -n:",
  "unstage-only": "--staged only unstages. Your changes stay in the files, so nothing is lost.",
  missingStash: "There's no {ref}. Check git stash list; the numbers shift every time a stash is dropped.",
  filesHeading: "Uncommitted changes, gone for good",
  untrackedHeading: "Files git doesn't track",
  ignoredHeading: "Ignored files (-x)",
  commitsHeading: "Commits the branch moves past",
  stashHeading: "Stash entries",
  modified: "edited",
  staged: "staged",
  new: "new, staged",
  conflict: "conflict",
  untracked: "untracked",
  ignored: "ignored",
  binary: "binary",
  precious: "hard to get back",
  rebuildable: "{count} you can rebuild: {list}",
  notPushed: "not pushed",
  commitsRecover: "Commits stay in the reflog for a while: git reset --hard HEAD@{1} undoes the move. Uncommitted changes have no such copy.",
  detached: "You're not on a branch (detached HEAD), so no branch keeps these commits. Run git branch keep-work first if you want them.",
  stashRecover: "Copy this id first; git stash apply {sha} brings it back until garbage collection.",
  keptUntracked: "Untracked files stay ({count}): only git clean deletes those.",
  keptIgnored: "Ignored files stay ({count}): add -x to clean them too.",
  keptStaged: "Staged changes stay ({count}): only the unstaged edits are thrown away.",
  keptDirs: "Untracked folders stay ({count}): add -d to delete folders.",
  keptExcluded: "Files matching -e stay ({count}).",
  keptSubmodules: "Submodule work stays ({count}): git only touches it with --recurse-submodules.",
  showMore: "Show {hidden} more",
  stashFirst: "Stash first",
  stashing: "Stashing…",
  stashed: "Saved to the stash. Your uncommitted changes are safe.",
  cancel: "Cancel",
  run: "Run",
  discard: "Discard and run",
  running: "Running…",
  listLabel: "What will be lost",
}
export type ResetHardMessages = typeof RESET_HARD_MESSAGES

const fill = (template: string, values: Record<string, string | number>) => template.replace(/\{(\w+)\}/g, (match, key: string) => String(values[key] ?? match))
const plural = (n: number, one: string, many: string) => `${n} ${n === 1 ? one : many}`
const button = "inline-flex h-9 items-center justify-center gap-2 rounded-md px-4 text-sm font-medium outline-none transition-colors focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50"

export interface ResetHardReadbackProps extends Omit<React.ComponentProps<"div">, "onChange"> {
  /** The command about to run, e.g. `git reset --hard origin/main`, `git clean -fdx`, `git checkout -- .`, `git stash drop`. */
  command: string
  /** Output of `git status --porcelain=v2 --branch --ignored` (v1 and -z work too). Add --ignored for clean -x. */
  status: string
  /** Output of `git diff HEAD --numstat` for the +/- line counts. */
  numstat?: string
  /** For reset --hard to another commit: `git log --oneline <target>..HEAD` (or parsed commits), newest first. */
  commits?: string | Commit[]
  /** The exact unpushed commits: `git rev-list @{u}..HEAD` output or a list of shas. Without it the newest `ahead` commits are marked, which is only exact for linear history. */
  unpushed?: string | string[]
  /** For stash drop/clear: the stash list, newest first. */
  stashes?: StashEntry[]
  /** Shows "Stash first". Receives the stash command that keeps everything at risk; may return a Promise. */
  onStash?: (command: string) => void | Promise<void>
  /** Runs the command. May return a Promise; the button shows a pending state and ignores repeat clicks. */
  onConfirm?: (command: string) => void | Promise<void>
  /** Shows a Cancel button. */
  onCancel?: () => void
  /** Rows to list per section before "Show more". */
  maxRows?: number
  /** Any visible string. */
  messages?: Partial<ResetHardMessages>
}

/**
 * Prevents `git reset --hard`, `git clean -fdx`, `git checkout -- .` and `git stash drop` from silently destroying work.
 * It reads porcelain status and lists exactly what goes: edited files with +/- lines, staged new files, untracked and
 * ignored files (with .env and keys first and node_modules folded away), commits the branch moves past with the
 * unpushed ones marked, and stash entries with the id to recover them. It also says what stays, and offers to stash first.
 */
export function ResetHardReadback({ command, status, numstat, commits, unpushed, stashes, onStash, onConfirm, onCancel, maxRows = 6, messages, className, ...props }: ResetHardReadbackProps) {
  const t = { ...RESET_HARD_MESSAGES, ...messages }
  const report = React.useMemo(() => whatWillBeLost({ command, status, numstat, commits, stashes, unpushed }), [command, status, numstat, commits, stashes, unpushed])
  const [pending, setPending] = React.useState<"" | "stash" | "run">("")
  const [stashed, setStashed] = React.useState(false)
  const [open, setOpen] = React.useState<string[]>([])
  const [announce, setAnnounce] = React.useState("")
  const busy = React.useRef(false)
  const version = React.useRef(0)
  const confirmRef = React.useRef<HTMLButtonElement>(null)
  const id = React.useId()

  // New status means the repo changed: an earlier "stashed" no longer describes it.
  React.useEffect(() => {
    version.current++
    setStashed(false)
  }, [command, status])

  const cmd = report.command
  const tracked = report.files.filter((f) => f.reason !== "untracked" && f.reason !== "ignored")
  const untracked = report.files.filter((f) => f.reason === "untracked")
  const ignored = report.files.filter((f) => f.reason === "ignored" && !f.rebuildable)
  const rebuildable = report.files.filter((f) => f.rebuildable)
  const lines = tracked.reduce((sum, f) => sum + (f.added ?? 0) + (f.removed ?? 0), 0)
  const atRisk = !report.harmless && (report.files.length > 0 || report.commits.length > 0 || report.stashes.length > 0)
  const stashCmd = stashFirstCommand(cmd)
  const canStash = !!onStash && !!stashCmd && atRisk && report.files.length > 0 && !stashed
  const stillAtRisk = report.commits.length > 0 || report.stashes.length > 0
  const destructive = atRisk && (!stashed || stillAtRisk)

  const summary = [
    report.files.length > 0 && !stashed && fill(t.summaryFiles, { files: plural(report.files.length, "file", "files") + (lines > 0 ? fill(t.linesSuffix, { lines }) : "") }),
    report.commits.length > 0 && fill(t.summaryCommits, { commits: plural(report.commits.length, "commit", "commits") }),
    report.unpushed > 0 && fill(t.summaryUnpushed, { unpushed: report.unpushed === report.commits.length ? "all of them" : report.unpushed }),
    report.stashes.length > 0 && fill(t.summaryStash, { stashes: plural(report.stashes.length, "stash entry", "stash entries") }),
  ].filter(Boolean).join(" ")

  const act = async (kind: "stash" | "run") => {
    const fn = kind === "stash" ? onStash : onConfirm
    if (!fn || busy.current) return
    busy.current = true
    setPending(kind)
    const started = version.current
    try {
      await fn(kind === "stash" ? stashCmd : String(command).trim())
      // Ignore a late answer if the repo changed while we waited.
      if (kind === "stash" && started === version.current) {
        setStashed(true)
        setAnnounce(t.stashed)
        requestAnimationFrame(() => confirmRef.current?.focus())
      }
    } catch {
      // The caller reports git failures; the buttons become usable again.
    } finally {
      busy.current = false
      setPending("")
    }
  }

  const section = (key: string, heading: string, rows: React.ReactNode[], icon: React.ReactNode) => {
    if (!rows.length) return null
    const shown = open.includes(key) || rows.length <= maxRows + 1 ? rows : rows.slice(0, maxRows)
    return (
      <section aria-labelledby={`${id}-${key}`} className="grid min-w-0 grid-cols-[minmax(0,1fr)] gap-1">
        <h4 id={`${id}-${key}`} className="flex items-center gap-1.5 text-xs font-medium text-muted-foreground">{icon}{heading}</h4>
        <ul className="divide-y rounded-md border text-xs">{shown}</ul>
        {shown.length < rows.length && (
          <button type="button" onClick={() => setOpen((o) => [...o, key])} className="justify-self-start rounded-md px-1.5 py-0.5 text-xs font-medium outline-none hover:underline focus-visible:ring-[3px] focus-visible:ring-ring/50">
            {fill(t.showMore, { hidden: rows.length - shown.length })}
          </button>
        )}
      </section>
    )
  }
  const fileRow = (f: LostFile) => (
    <li key={f.reason + f.path} data-reason={f.reason} className={cn("flex min-w-0 flex-wrap items-baseline gap-x-2 gap-y-0.5 px-2.5 py-1.5", f.precious && "bg-amber-500/5")}>
      <span className="min-w-0 flex-1 basis-48 font-mono [overflow-wrap:anywhere]">{f.path}</span>
      {f.precious && <span className="rounded border border-amber-500/40 px-1 text-[11px] font-medium text-amber-800 dark:text-amber-300">{t.precious}</span>}
      {f.reason !== "untracked" && f.reason !== "ignored" && <span className="text-muted-foreground">{t[f.reason]}</span>}
      {f.added !== null || f.removed !== null ? (
        <span className="font-mono tabular-nums">
          <span className="text-emerald-700 dark:text-emerald-400">+{f.added ?? 0}</span> <span className="text-red-700 dark:text-red-400">−{f.removed ?? 0}</span>
        </span>
      ) : null}
    </li>
  )

  const kept = [
    report.kept.untracked > 0 && cmd?.op !== "clean" && fill(t.keptUntracked, { count: report.kept.untracked }),
    report.kept.ignored > 0 && cmd?.op === "clean" && fill(t.keptIgnored, { count: report.kept.ignored }),
    report.kept.staged > 0 && !report.harmless && fill(t.keptStaged, { count: report.kept.staged }),
    report.kept.dirs > 0 && fill(t.keptDirs, { count: report.kept.dirs }),
    report.kept.excluded > 0 && fill(t.keptExcluded, { count: report.kept.excluded }),
    report.kept.submodules > 0 && fill(t.keptSubmodules, { count: report.kept.submodules }),
  ].filter(Boolean) as string[]
  const tone = !cmd || report.harmless ? "border-border bg-muted/40 text-muted-foreground" : !destructive ? "border-emerald-500/30 bg-emerald-500/5 text-emerald-800 dark:text-emerald-300" : "border-red-500/30 bg-red-500/5 text-red-800 dark:text-red-300"
  const headline = !cmd ? t.unknown : report.missingStash ? fill(t.missingStash, { ref: cmd.stashRef }) : report.harmless ? t[report.harmless] : stashed ? [t.stashed, summary].filter(Boolean).join(" ") : atRisk ? summary : t.nothing
  const HeadIcon = !cmd || report.harmless ? Info : !destructive ? CircleCheck : TriangleAlert

  return (
    <div data-slot="reset-hard-readback" data-state={stashed ? "stashed" : atRisk ? "at-risk" : "safe"} className={cn("w-full max-w-lg min-w-0 overflow-hidden rounded-xl border bg-background text-sm", className)} {...props}>
      <div className="flex items-center gap-2 border-b px-4 py-3">
        <History aria-hidden className="size-4 shrink-0 text-muted-foreground" />
        <h3 id={`${id}-title`} className="min-w-0 flex-1 font-mono text-sm font-medium [overflow-wrap:anywhere]">{String(command ?? "").trim()}</h3>
      </div>

      <div className="grid grid-cols-[minmax(0,1fr)] gap-3 px-4 py-3" aria-label={t.listLabel} role="group">
        <p className={cn("flex gap-2 rounded-md border p-3 font-medium", tone)}>
          <HeadIcon aria-hidden className="mt-0.5 size-4 shrink-0" />
          <span className="min-w-0">
            {headline}
          </span>
        </p>

        {section("files", t.filesHeading, tracked.map(fileRow), <FileWarning aria-hidden className="size-3.5" />)}
        {section("untracked", t.untrackedHeading, untracked.map(fileRow), <FileWarning aria-hidden className="size-3.5" />)}
        {section("ignored", t.ignoredHeading, [
          ...ignored.map(fileRow),
          ...(rebuildable.length ? [<li key="rebuild" className="px-2.5 py-1.5 text-muted-foreground [overflow-wrap:anywhere]">{fill(t.rebuildable, { count: rebuildable.length, list: rebuildable.map((f) => f.path).join(", ") })}</li>] : []),
        ], <FileWarning aria-hidden className="size-3.5" />)}
        {section("commits", t.commitsHeading, report.commits.map((c, i) => (
          <li key={c.sha + i} className="flex min-w-0 items-baseline gap-2 px-2.5 py-1.5">
            <code className="shrink-0 font-mono text-muted-foreground">{c.sha.slice(0, 7)}</code>
            <span className="min-w-0 flex-1 truncate" title={c.subject}>{c.subject}</span>
            {report.unpushedShas.includes(c.sha) && <span className="shrink-0 rounded border border-red-500/30 px-1 text-[11px] font-medium text-red-700 dark:text-red-300">{t.notPushed}</span>}
          </li>
        )), <GitCommitHorizontal aria-hidden className="size-3.5" />)}
        {report.commits.length > 0 && <p className="-mt-1.5 text-xs text-muted-foreground">{report.detached && <strong className="font-medium text-red-700 dark:text-red-300">{t.detached} </strong>}{t.commitsRecover}</p>}
        {section("stash", t.stashHeading, report.stashes.map((s) => {
          const added = s.files?.reduce((n, f) => n + (f.added ?? 0), 0) ?? 0
          const removed = s.files?.reduce((n, f) => n + (f.removed ?? 0), 0) ?? 0
          return (
            <li key={s.ref} className="grid gap-0.5 px-2.5 py-1.5">
              <div className="flex min-w-0 items-baseline gap-2">
                <code className="shrink-0 font-mono text-muted-foreground">{s.ref}</code>
                <span className="min-w-0 flex-1 [overflow-wrap:anywhere]">{s.message}</span>
                {s.files && <span className="shrink-0 font-mono tabular-nums">{plural(s.files.length, "file", "files")} <span className="text-emerald-700 dark:text-emerald-400">+{added}</span> <span className="text-red-700 dark:text-red-400">−{removed}</span></span>}
              </div>
              {s.sha && <span className="text-muted-foreground [overflow-wrap:anywhere]">{fill(t.stashRecover, { sha: s.sha })}</span>}
            </li>
          )
        }), <Archive aria-hidden className="size-3.5" />)}

        {kept.length > 0 && (
          <ul className="grid gap-1 text-xs text-muted-foreground">
            {kept.map((k) => <li key={k} className="flex gap-1.5"><CircleCheck aria-hidden className="mt-0.5 size-3.5 shrink-0 text-emerald-600 dark:text-emerald-400" />{k}</li>)}
          </ul>
        )}
      </div>

      <span role="status" className="sr-only">{announce}</span>
      <div className="flex flex-wrap justify-end gap-2 border-t px-4 py-3">
        {onCancel && <button type="button" onClick={onCancel} className={cn(button, "border bg-background hover:bg-accent")}>{t.cancel}</button>}
        {canStash && (
          <button type="button" onClick={() => act("stash")} disabled={!!pending} aria-busy={pending === "stash" || undefined} title={stashCmd} className={cn(button, "border bg-background hover:bg-accent")}>
            {pending === "stash" ? <Loader2 aria-hidden className="size-4 animate-spin" /> : <Archive aria-hidden className="size-4" />}
            {pending === "stash" ? t.stashing : t.stashFirst}
          </button>
        )}
        {onConfirm && cmd && (
          <button ref={confirmRef} type="button" onClick={() => act("run")} disabled={!!pending} aria-busy={pending === "run" || undefined} aria-describedby={`${id}-title`} className={cn(button, destructive ? "bg-destructive text-white hover:bg-destructive/90" : "bg-primary text-primary-foreground hover:bg-primary/90")}>
            {pending === "run" && <Loader2 aria-hidden className="size-4 animate-spin" />}
            {pending === "run" ? t.running : destructive ? t.discard : t.run}
          </button>
        )}
      </div>
    </div>
  )
}
